    "CacheTtlMinutes" integer,
    "MaxRetries" integer,
    "ProviderSettings" jsonb,
    "ParameterSchema" jsonb,
    "Description" character varying(1000),
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_FunctionConfigurations" PRIMARY KEY ("Id")
);


CREATE TABLE "FunctionCosts" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "CostName" character varying(200) NOT NULL,
    "ProviderType" integer NOT NULL,
    "Purpose" integer,
    "Description" character varying(500),
    "BaseCost" numeric(18,8),
    "PricingModel" integer NOT NULL,
    "CostPerExecution" numeric(18,8),
    "CostPerResult" numeric(18,8),
    "CostPerToken" numeric(18,8),
    "CostPerMinute" numeric(18,8),
    "TieredPricing" jsonb,
    "PricingConfiguration" jsonb,
    "IsActive" boolean NOT NULL,
    "EffectiveDate" timestamp with time zone NOT NULL,
    "ExpiryDate" timestamp with time zone,
    "Priority" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_FunctionCosts" PRIMARY KEY ("Id")
);


CREATE TABLE "FunctionExecutionClaims" (
    "VirtualKeyId" integer NOT NULL,
    "KeyHash" character varying(64) NOT NULL,
    "Fingerprint" character varying(64) NOT NULL,
    "ExecutionId" uuid NOT NULL,
    "BillingGroupId" integer NOT NULL,
    "CreatedAtUtc" timestamp with time zone NOT NULL,
    "State" character varying(16) NOT NULL,
    "ResultJson" jsonb,
    "BilledAtUtc" timestamp with time zone,
    CONSTRAINT "PK_FunctionExecutionClaims" PRIMARY KEY ("VirtualKeyId", "KeyHash"),
    CONSTRAINT "CK_FunctionExecutionClaims_Billed" CHECK ("BilledAtUtc" IS NULL OR "State" = 'completed'),
    CONSTRAINT "CK_FunctionExecutionClaims_Result" CHECK (("State" = 'completed') = ("ResultJson" IS NOT NULL)),
    CONSTRAINT "CK_FunctionExecutionClaims_State" CHECK ("State" IN ('claimed', 'dispatching', 'completed', 'uncertain'))
);


CREATE TABLE "GlobalSettings" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Key" character varying(100) NOT NULL,
    "Value" character varying(2000) NOT NULL,
    "Description" character varying(500),
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_GlobalSettings" PRIMARY KEY ("Id")
);


CREATE TABLE "MediaCleanupApprovals" (
