    "AffinityTtlSeconds" integer NOT NULL,
    "MaxAffinityScorePenalty" numeric(4,3) NOT NULL,
    "IsEnabled" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_ModelRoutePolicies" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_ModelRoutePolicy_Affinity" CHECK ("AffinityTtlSeconds" > 0 AND "MaxAffinityScorePenalty" >= 0),
    CONSTRAINT "CK_ModelRoutePolicy_Weights" CHECK ("CostWeight" >= 0 AND "SpeedWeight" >= 0 AND "QualityWeight" >= 0)
);


CREATE TABLE "ProviderMetadataSyncRuns" (
