    "ModelId" character varying(100) NOT NULL,
    "ModelCostId" integer NOT NULL,
    "PricingType" character varying(20) NOT NULL,
    "InputParameters" jsonb NOT NULL DEFAULT '{}',
    "MatchedRule" jsonb,
    "UsedDefaultRate" boolean NOT NULL,
    "AppliedRate" numeric(10,8) NOT NULL,
    "Quantity" numeric(10,4) NOT NULL,
    "CalculatedCost" numeric(12,8) NOT NULL,
    "RequestId" character varying(100),
    CONSTRAINT "PK_PricingAuditEvents" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_PricingAuditEvents_VirtualKeys_VirtualKeyId" FOREIGN KEY ("VirtualKeyId") REFERENCES "VirtualKeys" ("Id") ON DELETE CASCADE
);


CREATE TABLE "RequestLogs" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "VirtualKeyId" integer NOT NULL,
    "ModelName" character varying(100) NOT NULL,
    "ProviderId" integer,
    "ProviderType" character varying(50),
    "ModelProviderMappingId" integer,
    "PromptCachingEligible" boolean NOT NULL,
    "PromptCachingPolicyApplied" boolean NOT NULL,
    "CachedReadSavings" numeric(18,8) NOT NULL,
    "CacheWritePremium" numeric(18,8) NOT NULL,
    "RoutingAffinityUsed" boolean NOT NULL,
    "RoutingDecisionReason" character varying(50),
    "RoutingFailoverCount" integer NOT NULL,
    "RequestType" character varying(50) NOT NULL,
    "InputTokens" integer NOT NULL,
    "OutputTokens" integer NOT NULL,
    "CachedInputTokens" integer,
    "CachedWriteTokens" integer,
    "Cost" numeric(12,8) NOT NULL,
    "BillingMethod" integer,
    "ProviderReportedCostUsd" numeric(18,8),
    "ProviderCostMarkupMultiplier" numeric(18,8),
    "BilledAtUtc" timestamp with time zone,
    "ResponseTimeMs" double precision NOT NULL,
    "Timestamp" timestamp with time zone NOT NULL,
    "UserId" character varying(100),
    "ClientIp" character varying(50),
    "RequestPath" character varying(256),
    "StatusCode" integer,
    "Metadata" jsonb,
    CONSTRAINT "PK_RequestLogs" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_RequestLogs_VirtualKeys_VirtualKeyId" FOREIGN KEY ("VirtualKeyId") REFERENCES "VirtualKeys" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "VirtualKeySpendHistory" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "VirtualKeyId" integer NOT NULL,
    "Amount" numeric(12,8) NOT NULL,
    "Date" timestamp with time zone NOT NULL,
    "Timestamp" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_VirtualKeySpendHistory" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_VirtualKeySpendHistory_VirtualKeys_VirtualKeyId" FOREIGN KEY ("VirtualKeyId") REFERENCES "VirtualKeys" ("Id") ON DELETE CASCADE
);


CREATE TABLE "ModelIdentifiers" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ModelId" integer NOT NULL,
    "IsEnabled" boolean NOT NULL,
    "MaxInputTokens" integer,
    "MaxOutputTokens" integer,
    "InputModalities" jsonb,
    "OutputModalities" jsonb,
    "OperationalCapabilities" jsonb,
    "CapabilitySource" integer,
    "CapabilitiesLastVerifiedAt" timestamp with time zone,
    "ProviderVariation" text,
    "QualityScore" numeric,
    "SpeedScore" numeric,
    "Identifier" character varying(200) NOT NULL,
    "Provider" integer,
    "ModelCostId" integer,
    "IsPrimary" boolean NOT NULL,
    "Metadata" text,
