    CONSTRAINT "FK_ModelIdentifiers_ModelCosts_ModelCostId" FOREIGN KEY ("ModelCostId") REFERENCES "ModelCosts" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_ModelIdentifiers_Models_ModelId" FOREIGN KEY ("ModelId") REFERENCES "Models" ("Id") ON DELETE CASCADE
);


CREATE TABLE "ModelProviderMappings" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ModelAlias" character varying(100) NOT NULL,
    "ProviderModelId" character varying(100) NOT NULL,
