    CONSTRAINT "FK_ModelProviderMappings_ModelIdentifiers_ModelProviderTypeAss~" FOREIGN KEY ("ModelProviderTypeAssociationId") REFERENCES "ModelIdentifiers" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ModelProviderMappings_Providers_ProviderId" FOREIGN KEY ("ProviderId") REFERENCES "Providers" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "ProviderMetadataDriftItems" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ModelProviderMappingId" integer NOT NULL,
    "ProviderId" integer NOT NULL,
    "OpenRouterModelId" character varying(200) NOT NULL,
